Method.Implementation:
    Set tArr = []
    set ^webService("TPs") = "Start "_ $ZDATETIME($HOROLOG,3, 1)

	Set rs = ##class(%SQL.Statement).%ExecDirect(,"SELECT * FROM IHC_ERP_TPManage.TradingPartner order by Name")
	While rs.%Next() {
		if (rs.%Get("Name") '= "")
		{
			Do tArr.%Push({
				"Operation":"TPs",
				"id" : (rs.%Get("ID")),
				"Name":  (rs.%Get("Name")),
				"TPtype":    (rs.%Get("Type")),
				"BusinessContact":    			(rs.%Get("BusinessContact")),				
				"CommunicationContact": 			(rs.%Get("CommunicationContact")),
				"Folder":        	(rs.%Get("Folder")),
				"CommunicationProtocol":        	(rs.%Get("CommunicationProtocol")),
				"Notes":        	(rs.%Get("Notes")),
			"InterchangeIdQualifier":      (rs.%Get("InterchangeIdQualifier")),
			"PartnerInterchangeIdQualifier":      (rs.%Get("PartnerInterchangeIdQualifier"))				
			})
		}
	}
	Do ..%SetStatusCode(200)

	return tArr


Do ..%SetStatusCode(200)
Set obj = {}
Set tp = ##class(IHC.ERP.TPManage.TradingPartner).%OpenId(id)
If '$IsObject(tp) {
	&SQL(select ID into :tpId FROM IHC_ERP_TPManage.TradingPartner where Name = :id)
	if SQLCODE = 0
	{			
		Set tp = ##class(IHC.ERP.TPManage.TradingPartner).%OpenId(tpId)
	}
} 

If '$IsObject(tp) {
	Set obj = {
		"ID": (id),
		"Error": 	"TP not found"
	}
} Else {

	Set obj = {
		"Operation":"GetTp",
		"id": (tp.%Id()),
		"Name": 		(tp.Name),
		"CommunicationContact":        (tp.CommunicationContact),
		"BusinessContact":   		(tp.BusinessContact),
		"Folder":      (tp.Folder),
		"CommunicationProtocol":      (tp.CommunicationProtocol),
		"InterchangeIdQualifier":      (tp.InterchangeIdQualifier),
		"PartnerInterchangeIdQualifier":      (tp.PartnerInterchangeIdQualifier),
		"TPtype":        (tp.Type),
		"Notes": (tp.Notes)
	}


}
return obj

set ^webService("NewTp") = "Start"
If '..GetJSONFromRequest(.obj) {
	Set %response.Status = 400 // ..#HTTP400BADREQUEST
	Set error = {"errormessage": "JSON not found"}
	Write error.%ToJSON()
	Quit $$$OK
}

If '..ValidateJSONForTp(obj,.error) {
	Set %response.Status = 400 // ..#HTTP400BADREQUEST
	Write error.%ToJSON()
	Quit $$$OK
}

Set cm = ##class(IHC.ERP.TPManage.TradingPartner).%New()
Do ..CopyToTpFromJSON(.cm,obj)

Set sc = cm.%Save()

Set result={}
do result.%Set("Status",$s($$$ISERR(sc):$system.Status.GetOneErrorText(sc),1:"OK"))
if ($$$ISOK(sc)) {
	do result.%Set("id", cm.%Id())
}
do result.%Set("Operation","NewTp")
do result.%Set("NameSPACE", $NameSPACE)
do result.%Set("Name", cm.Name)
set ^webService("NewTp Added") = cm.%Id()
Quit result

	Set result={}
	set ^webService("UpdateTp") = "UpdateTp " 
   If '..GetJSONFromRequest(.obj) {
		Set %response.Status = 400 // ..#HTTP400BADREQUEST
		Set error = {"errormessage": "JSON not found"}
		Write error.%ToJSON()
		Quit error
	}
	set tradingPartnerId = ""
	If obj.%Get("id") = "" {
		If obj.%Get("OrigName") = "" {
			do result.%Set("Error", "ID or OrigName required for Update")
			Quit result
		}
		set ^webService("UpdateTp OrigName") = obj.OrigName
		Set tpNm =obj.OrigName

		&SQL(select ID into :tradingPartnerId FROM IHC_ERP_TPManage.TradingPartner where Name = :tpNm)
		if SQLCODE '= 0
		{			
				do result.%Set("Error", "SQL Error in finding TP: " _ SQLCODE)
				return result
		}
		if (tradingPartnerId = "")
		{
				do result.%Set("Error", "ID for TP is empty " _ tpNm)
				return result

		}

	}
	else
	{	
		set tradingPartnerId =	obj.id
		set ^webService("UpdateTp ID") = tradingPartnerId
	}

	Set cm = ##class(IHC.ERP.TPManage.TradingPartner).%OpenId(tradingPartnerId)
	If $IsObject(cm) {
		Do ..UpdateToTpFromJSON(.cm,obj)

		Set sc = cm.%Save()

		do result.%Set("Status",$s($$$ISERR(sc):$system.Status.GetOneErrorText(sc),1:"OK"))
		if ($$$ISOK(sc)) {
			do result.%Set("ID", cm.%Id())
		}
		do result.%Set("Operation","UpdateTp")
		do result.%Set("NameSPACE", $NameSPACE)
		do result.%Set("Name", cm.Name)
	}
	else
	{
		do result.%Set("Error", "TP with id " _ obj.id _ " not found")
	}

	Quit result

	Set result={}
	set ^webService("DeleteTp") = "DeleteTp - " _ $ZDATETIME($HOROLOG,3, 1)
   If '..GetJSONFromRequest(.obj) {
		Set %response.Status = 400 // ..#HTTP400BADREQUEST
		Set error = {"errormessage": "JSON not found"}
		Write error.%ToJSON()
		Quit $$$OK
	}
	set tpNm = obj.%Get("Name")
	set ^webService("DeleteTp Name") = tpNm
	If tpNm = "" {
		do result.%Set("Error", "ID required for Delete")
	}
	else
	{		
		set ^webService("DeleteTp SQL") = tpNm
		&SQL(Delete IHC_ERP_TPManage.TradingPartner where Name = :tpNm)
		if SQLCODE = 0
		{			
			do result.%Set("Status", "TP with name " _ tpNm _ " deleted")
		}
		else
		{
			do result.%Set("Error", "TP with name " _ tpNm _ " not deleted, SQLCode: " _ SQLCODE _ " / " _ $SYSTEM.SQL.Functions.SQLCODE(SQLCODE))
		}
		set ^webService("DeleteTp SQLCODE") = SQLCODE
	}
	Quit result

Set error = {}

If obj.%Get("Name") = "" {
	Set error.errormessage = "Name was blank"
	Quit 0
}	

If (obj.%Get("Type") = "" || obj.%Get("TPtype") = "") {
	Set error.errormessage = "Type was blank"
	Quit 0
}
set ^webService("Name") = "ValidateJSONForTp: " _ obj.%Get("Name")
Quit 1

	Set result={}
   	If '..GetJSONFromRequest(.obj) {
		Set %response.Status = 200 // ..#HTTP400BADREQUEST
		Set error = {"errormessage": "JSON not found"}
		Write error.%ToJSON()
		Quit error
	}

	If '..ValidateJSONForTpId(obj,.error) {
		Set %response.Status = 200 // ..#HTTP400BADREQUEST
		Set error = {"errormessage": "Requird fields not found"}
		Write error.%ToJSON()
		Quit error
	}

	Set cm = ##class(IHC.ERP.TPManage.TpId).%New()
	IF (..CopyToTpIdFromJSON(.cm,obj) '= $$$OK)
	{
		Set %response.Status = 200 // ..#HTTP400BADREQUEST
		Set error = {"errormessage": "resolving fields not found"}
		Quit error
	}

	Set sc = cm.%Save()


	do result.%Set("Status",$s($$$ISERR(sc):$system.Status.GetOneErrorText(sc),1:"OK"))
	if ($$$ISOK(sc)) {
		do result.%Set("id", cm.%Id())
	}
	do result.%Set("Operation", "NewTpId")
	do result.%Set("TPID", cm.TPID)
	do result.%Set("TPFK", cm.TPFK.Name)

	Do result.%Set("Create DtTm", cm.CreatedDtTM)
	Quit result

	Set result={}
   	If '..GetJSONFromRequest(.obj) {
		Set %response.Status = 400 // ..#HTTP400BADREQUEST
		Set error = {"errormessage": "JSON not found"}
		Write error.%ToJSON()
		Quit $$$OK
	}
	If obj.%Get("id") = "" {
		do result.%Set("Error", "ID required for Update")
	}
	else
	{	
		Set tpId = ##class(IHC.ERP.TPManage.TpId).%OpenId(obj.id)
		If $IsObject(tpId) {
			Do ..UpdateToTpIdFromJSON(.tpId,obj)

			Set sc = tpId.%Save()

			do result.%Set("Status",$s($$$ISERR(sc):$system.Status.GetOneErrorText(sc),1:"OK"))
			if ($$$ISOK(sc)) {
				do result.%Set("ID", tpId.%Id())
			}
			do result.%Set("TPID", tpId.TPID)
			do result.%Set("TPFK", tpId.TPFK.Name)
			do result.%Set("Operation","UpdateTpId")

		}
		else
		{
			do result.%Set("Error", "TPID with id " _ obj.id _ " not found")
		}
	}
	Quit result

   	Do ..%SetStatusCode(200)

	Set tp = ##class(IHC.ERP.TPManage.TpId).%OpenId(id)
	If '$IsObject(tp) {

		&SQL(select ID into :tpId FROM IHC_ERP_TPManage.TpId where TPID = :id)
		if SQLCODE = 0
		{			
			Set tp = ##class(IHC.ERP.TPManage.TpId).%OpenId(tpId)
		}
	} 
	If $IsObject(tp) { 

		Set obj = {
			"Operation": "GetTpId",
			"id": (tp.%Id()),
			"TPID":        (tp.TPID),
			"CreatedDtTM": (tp.CreatedDtTM),
			"LastmodDtTM":   		(tp.LastmodDtTM),
			"Type":        (tp.Type),
			"TPFK": (tp.TPFK.Name)
		}
		Do ..%SetStatusCode(200)
		return obj

	}
	else
	{
		Set %response.Status = 200
		Set error = {"Error": ("TP ID not found: " _ id)}
		Quit error
	}

   set implArr = []

	&sql(DECLARE WPCursor CURSOR FOR SELECT distinct tpid.ID, tpid.TPID, tpid.TYPE
	INTO :id, :tpid, :type
	from IHC_ERP_TPManage.TradingPartner tp, IHC_ERP_TPManage.TpId tpid
	where tpid.TPFK = tp.ID )

	&sql(OPEN WPCursor)
        if (SQLCODE'=0) {
	         Do implArr.%Push(
				{
					"TP":    (name),
					"Error": (SQLCODE)
				})
				QUIT implArr
        }
   FOR { 
   		&sql(FETCH WPCursor)
        if (SQLCODE = 0) {
	        Do implArr.%Push(
			{
				"id": (id),
			"TPID":        (tpid),
			"Type":        (type)	
		})
        }
        else
        {
	        if (%ROWCOUNT = 0)
	        {
		        Do implArr.%Push(
				{
					"TP":    (name),
					"Error": ("Number of rows: " _ %ROWCOUNT)
				})
	        }
	        QUIT
        }
   }
   Quit implArr

   set implArr = []

	&sql(DECLARE WPCursor CURSOR FOR SELECT distinct tpid.ID, tpid.TPID, tpid.TYPE
	INTO :id, :tpid, :type
	from IHC_ERP_TPManage.TradingPartner tp, IHC_ERP_TPManage.TpId tpid
	where tpid.TPFK = tp.ID and tp.Type in ('OWNER','PAYER') order by tpid.TPID) 

	&sql(OPEN WPCursor)
        if (SQLCODE'=0) {
	         Do implArr.%Push(
				{
					"TP":    (name),
					"Error": (SQLCODE)
				})
				QUIT implArr
        }
   FOR { 
   		&sql(FETCH WPCursor)
        if (SQLCODE = 0) {
	        Do implArr.%Push(
			{
				"id": (id),
			"TPID":        (tpid),
			"Type":        (type)	
		})
        }
        else
        {
	        if (%ROWCOUNT = 0)
	        {
		        Do implArr.%Push(
				{
					"TP":    (name),
					"Error": ("Number of rows: " _ %ROWCOUNT)
				})
	        }
	        QUIT
        }
   }
   Quit implArr

   set implArr = []
	set ^webService("TpIdsForTP") = name	
	&sql(DECLARE WPCursor CURSOR FOR SELECT tpid.ID, tpid.TPID, tpid.Type
	INTO :id, :tpid, :type
	from IHC_ERP_TPManage.TradingPartner tp, IHC_ERP_TPManage.TpId tpid
	where tpid.TPFK = tp.ID and tp.Name = :name order by tp.Name)

	&sql(OPEN WPCursor)
    if (SQLCODE'=0) {
	         Do implArr.%Push(
				{
					"TPID":    (name),
					"Error": (SQLCODE)
				})
				QUIT implArr
        }
   FOR { 
   		&sql(FETCH WPCursor)
        if (SQLCODE = 0) {

	        Do implArr.%Push(
			{
				"id": (id),
			"TPID":        (tpid),
			"Type":        (type),
			"Name": (name)	
		})
        }
        else {
        	QUIT
        }

   }
   set ^webService("TpIdsForTP return") = implArr.%Size()
   Quit implArr

Set error = {}
If obj.%Get("Type") = "" {
	Set error.errormessage = "Type was blank"
	Quit 0
}	

If obj.%Get("TPID") = "" {
	Set error.errormessage = "TPID was blank"
	Quit 0
}
set ^webService("TpIdsForTP") = "Validated"
Quit 1

    Set result={}
    set ^webService("NewTpLink") = "NewTpLink"
   	If '..GetJSONFromRequest(.obj) {
		// Set %response.Status = 400 // ..#HTTP400BADREQUEST
		Set error = {"errormessage": "JSON not found"}
		Write error.%ToJSON()
		Quit error
	}
	set ^webService("NewTpLink") = "NewTpLink ValidateJSONForTpLink"
	If '..ValidateJSONForTpLink(obj,.error) {
		// Set %response.Status = 400 // ..#HTTP400BADREQUEST
		Set error = {"errormessage": ("TP validation error: " _ error.errormessage)}
		Write error.%ToJSON()
		Quit error
	}
	set ^webService("NewTpLink") = "NewTpLink CopyToTpLinkFromJSON"
	Set cm = ##class(IHC.ERP.TPManage.TradeLink).%New()
	set st = ..CopyToTpLinkFromJSON(.cm,obj)
	IF ( st '= $$$OK)
	{
		// Set %response.Status = 400 // ..#HTTP400BADREQUEST
		Set error = {"Status": ("All fields not found: " _ st)}
		Write error.%ToJSON()
		Quit error
	}
	set ^webService("NewTpLink") = "NewTpLink Save"
	Set sc = cm.%Save()


	do result.%Set("Status",$s($$$ISERR(sc):$system.Status.GetOneErrorText(sc),1:"OK"))
	if ($$$ISOK(sc))
	{
		do result.%Set("id", cm.%Id())
	}
	do result.%Set("TransactionType", obj.TransactionType)
	do result.%Set("Name", cm.Name)
	do result.%Set("Operation","NewTpLink")

	Do result.%Set("Create DtTm", cm.CreatedDtTM)
	Quit result

	Set result={}
	set ^webService("UpdateTpLink") = "UpdateTpLink"
   	If '..GetJSONFromRequest(.obj) {
		Set %response.Status = 400 // ..#HTTP400BADREQUEST
		Set error = {"errormessage": "JSON not found"}	
		Quit error
	}

	set ^webService("UpdateTpLink ID") = "UpdateTpLink" _ obj.%Get("ID") 

	If obj.%Get("ID") = "" {
		set lnkNm = obj.%Get("Link") 
		set ^webService("UpdateTpLink Link") = "UpdateTpLink: " _ lnkNm
		&SQL(select ID into :tpId FROM IHC_ERP_TPManage.TradeLink where Name = :lnkNm)
		if SQLCODE = 0
		{			
			Set tpLink = ##class(IHC.ERP.TPManage.TradeLink).%OpenId(tpId)
		}
		else
		{
			set ^webService("UpdateTpLink error") = "UpdateTpLink: " _ lnkNm
			do result.%Set("Error", "Link not found in IHC_ERP_TPManage.TradeLink: " _ lnkNm)
			QUIT result
		}

	}
	else
	{
		Set tpLink = ##class(IHC.ERP.TPManage.TradeLink).%OpenId(obj.ID)
	}
	If $IsObject(tpLink) {
		set ^webService("UpdateTpLink ID") = "UpdateTpLink- " _ tpLink.%Id()

			set st = ..UpdateToTpLinkFromJSON(.tpLink,obj)

			IF ( st '= $$$OK)
			{
				// Set %response.Status = 400 // ..#HTTP400BADREQUEST
				Set error = {"errormessage": ("All fields not found: " _ st)}
				Write error.%ToJSON()
				set ^webService("UpdateTpLink Link") = "All fields not found " 
				Quit error
			}
			Set sc = tpLink.%Save()
			set res = $s($$$ISERR(sc):$system.Status.GetOneErrorText(sc),1:"OK")

			do result.%Set("Status",res)
			set ^webService("UpdateTpLink Link") = "UpdateTpLink: " _ res
			if ($$$ISOK(sc)) {

				do result.%Set("ID", tpLink.%Id())
			}
			do result.%Set("Operation","UpdateTpLink")
			do result.%Set("LastmodDtTM",   (tpLink.LastmodDtTM))

			do result.%Set("Ack",  (tpLink.Ack))

			do result.%Set("Link", (tpLink.Name))

	}
	else
	{
		set ^webService("UpdateTpLink Link") = "UpdateTpLink: Error ID or Name required"
		do result.%Set("Error", "ID or Name required for TRADELINKS Update")
	}

	Quit result

 	Do ..%SetStatusCode(200)
 	set ^webService("GetTpLink") = "GetTpLink " _ id
	#dim tpLink As IHC.ERP.TPManage.TradeLink	
	Set tpLink = ##class(IHC.ERP.TPManage.TradeLink).%OpenId(id)
	If '$IsObject(tpLink) {

		&SQL(select ID into :tpLinkId FROM IHC_ERP_TPManage.TradeLink where Name = :id)
		if SQLCODE = 0
		{			
			Set tpLink = ##class(IHC.ERP.TPManage.TradeLink).%OpenId(tpLinkId)
		}
	}

	If $IsObject(tpLink) { 
	    set ^webService("GetTpLink") = "GetTpLink ID for Name: " _ tpLink.Name _"= " _ tpLink.%Id()


		 set ^webService("GetTpLink Obj") = "GetTpLink Name: " _ tpLink.Name _", Ack: " _ tpLink.Ack 
		 try
		 {
		Set obj = {
				"Link": (id),
				"TransactionType":(tpLink.TransactionType.Name),
				"Version": (tpLink.TransactionType.Version),			
			"Operation":"GetTpLink",
			"ID": (tpLink.%Id()),
			"Name": 		(tpLink.Name),
			"LastmodDtTM":   (tpLink.LastmodDtTM),
			"IsaSenderId":   (tpLink.IsaSenderId.TPID),
			"IsaReceiverId": (tpLink.IsaReceiverId.TPID),
			"GsSenderId":    (tpLink.GsSenderId.TPID),
			"GsReceiverId":  (tpLink.GsReceiverId.TPID),
			"FileName": (tpLink.FileName),
			"Ack":  (tpLink.Ack),
			"Separators": (tpLink.Separators),
			"Direction": (tpLink.Direction),
			"Folder": (tpLink.Folder)
		}
		set ^webService("GetTpLink Return") = "GetTpLink Name: " _ tpLink.Name
		Do ..%SetStatusCode(200)
		return obj
		 } catch exp{
			 set ^webService("GetTpLink exp") = "GetTpLink Exp: " _ exp.Location _", " _ exp.Code
		 }

	}
	else
	{
		Set %response.Status = 200
		Set error = {"Error": ("TPLink ID not found: " _ id _ ", " _ tpLinkId)}
		Quit error
	}

	Do ..%SetStatusCode(200)
	set ^webService("DelTpLink") = "DelTpLink"

	 Set result={}
   	If '..GetJSONFromRequest(.obj) {
		// Set %response.Status = 400 // ..#HTTP400BADREQUEST
		Set error = {"errormessage": "JSON not found"}
		Write error.%ToJSON()
		Quit error
	}
	set ^webService("DelTpLink") = "DelTpLink " _ obj.id
	#dim tpLink As IHC.ERP.TPManage.TradeLink	
	Set tpLink = ##class(IHC.ERP.TPManage.TradeLink).%OpenId(obj.id)
	If '$IsObject(tpLink) {
		set nm = obj.id
		&SQL(select ID into :tpLinkId FROM IHC_ERP_TPManage.TradeLink where Name = :nm)
		if SQLCODE = 0
		{			
			Set tpLink = ##class(IHC.ERP.TPManage.TradeLink).%OpenId(tpLinkId)
		}
	} 
	If $IsObject(tpLink) {

		Set sc = tpLink.%DeleteId(tpLinkId)

		set ^webService("DelTpLink") = "DelTpLink " _ obj.id _ ", stat: " _ sc
		do result.%Set("Status",$s($$$ISERR(sc):$system.Status.GetOneErrorText(sc),1:"OK"))

		Set %response.Status = 200
		do result.%Set("Update", ("TPLink ID deleted " _ obj.id ))
	}
	else
	{
		Set result = {"Error": ("TPLink ID not found: " _ obj.id )}
	}
	Quit result

	set implArr = []
	set ^webService("GetLinksForTPID") = "GetTpLink " _ TPID	
	&sql(DECLARE WPCursor CURSOR FOR SELECT lnk.ID, tt.Name, lnk.Name, lnk.Direction, lnk.Separators, lnk.Folder, Version, Ack, GsReceiverId, 
		GsSenderId, IsaReceiverId, IsaSenderId, FileName 
		INTO :lnkId, :trans, :lnkNm, :direction, :sep, :folder, :ver,:Ack,
		:gsReceiverId, :gsSenderId, :isaReceiverId, :isaSenderId, :flNm

		from IHC_ERP_TPManage.TradeLink lnk, IHC_ERP_TPManage.TpId tpid, 
		IHC_ERP_TPManage.TransactionType tt
		where (tpid.ID = lnk.IsaSenderId 
		OR		tpid.ID = lnk.IsaReceiverId 
		OR		tpid.ID = lnk.GsSenderId 
		OR		tpid.ID = lnk.IsaReceiverId) 

		AND TPID = :TPID AND tt.ID = lnk.TransactionType order by lnk.Name)
	&sql(OPEN WPCursor)
        if (SQLCODE'=0) {
	        set ^webService("GetLinksForTPID OPEN") = SQLCODE
	         Do implArr.%Push(
				{
					"TPID":    (TPID),
					"Error": (SQLCODE)
				})
				QUIT implArr
        }
        set ^webService("GetLinksForTPID OPEN") = "GetTpLink " _ TPID
   FOR { 
   		&sql(FETCH WPCursor)
        if (SQLCODE = 0) {

		Set tpId = ##class(IHC.ERP.TPManage.TpId).%OpenId(gsReceiverId)
		If $IsObject(tpId) {

			set gsReceiverTPIP = tpId.TPID
		}
		Set tpId = ##class(IHC.ERP.TPManage.TpId).%OpenId(gsSenderId)
		If $IsObject(tpId) {

			set gsSenderTPIP = tpId.TPID
		}
		Set tpId = ##class(IHC.ERP.TPManage.TpId).%OpenId(isaReceiverId)
		If $IsObject(tpId) {

			set isaReceiverTPIP = tpId.TPID
		}
		Set tpId = ##class(IHC.ERP.TPManage.TpId).%OpenId(isaSenderId)
		If $IsObject(tpId) {

			set isaSenderTPIP = tpId.TPID
		}
			Do implArr.%Push(
			{
				"TPID":    (TPID),
				"id": (lnkId),
				"Link": (lnkNm),
				"TransactionType":(trans),
				"Direction":(direction),
				"Separators":(sep),
				"Folder":(folder),
				"Version": (ver),
				"FileName": (flNm),
				"Ack": (Ack),

				"GsReceiverId": (gsReceiverTPIP),
				"GsSenderId": (gsSenderTPIP),
				"IsaReceiverId": (isaReceiverTPIP),
				"IsaSenderId": (isaSenderTPIP)

			})
        }
        else
        {
	        if (%ROWCOUNT = 0)
	        {
		        Do implArr.%Push(
				{
					"TPID":    (TPID),
					"Link": ("No links for: " _ TPID),
					"Error": ("Number of rows: " _ %ROWCOUNT)
				})
	        }
	        QUIT
        }

	}
	set ^webService("GetLinksForTPID Complete") = "GetTpLink " _ implArr.%Size()
	Quit implArr

	set implArr = []

	&sql(DECLARE WPCursor CURSOR FOR SELECT tt.Name, lnk.Name, Version, TransactionType,  
	    Ack, GsReceiverId, 
		GsSenderId, IsaReceiverId, IsaSenderId
		INTO :trans, :lnkNm, :version, :type, 
		:Ack, :gsReceiverIP, :gsSenderIP, :isaReceiverId, 
		:isaSenderId
		from IHC_ERP_TPManage.TradeLink lnk, IHC_ERP_TPManage.TpId tpid, IHC_ERP_TPManage.TransactionType tt
		where (tpid.ID = lnk.IsaSenderId 
		OR		tpid.ID = lnk.IsaReceiverId 
		OR		tpid.ID = lnk.GsSenderId 
		OR		tpid.ID = lnk.IsaReceiverId) 
		AND tt.Name = :TPID AND tt.ID = lnk.TransactionType)
	&sql(OPEN WPCursor)
        if (SQLCODE'=0) {
	         Do implArr.%Push(
				{
					"TPID":    (TPID),
					"Error": (SQLCODE)
				})
				QUIT implArr
        }
   FOR { 
   		&sql(FETCH WPCursor)
        if (SQLCODE = 0) {

		Set tpId = ##class(IHC.ERP.TPManage.TpId).%OpenId(gsReceiverId)
		If $IsObject(tpId) {

			set gsReceiverTPIP = tpId.TPID
		}
		Set tpId = ##class(IHC.ERP.TPManage.TpId).%OpenId(gsSenderId)
		If $IsObject(tpId) {

			set gsSenderTPIP = tpId.TPID
		}
		Set tpId = ##class(IHC.ERP.TPManage.TpId).%OpenId(isaReceiverId)
		If $IsObject(tpId) {

			set isaReceiverTPIP = tpId.TPID
		}
		Set tpId = ##class(IHC.ERP.TPManage.TpId).%OpenId(isaSenderId)
		If $IsObject(tpId) {

			set isaSenderTPIP = tpId.TPID
		}
			Do implArr.%Push(
			{
				"TPID":    (TPID),
				"Link": (lnkNm),
				"TransactionType":(trans),
				"Version": (version),

				"Ack": (Ack),

				"GsReceiverId": (gsReceiverTPIP),
				"GsSenderId": (gsSenderTPIP),
				"IsaReceiverId": (isaReceiverTPIP),
				"IsaSenderId": (isaSenderTPIP)
			})
        }
        else
        {
	        if (%ROWCOUNT = 0)
	        {
		        Do implArr.%Push(
				{
					"TPID":    (TPID),
					"Error": ("Number of rows: " _ %ROWCOUNT)
				})
	        }
	        QUIT
        }

	}

	Quit implArr

