		}
	} 
	If $IsObject(tpId) {
		set id = tpId.%Id()		
		&SQL(DELETE FROM IHC_ERP_TPManage.TpId where id = :id)
		if (SQLCODE = 0)
		{
		do result.%Set("Status","OK, TPID deleted")
		}
		else
		{
			do result.%Set("Error", "TPID: " _ obj.id _" not deleted, " _ SQLCODE _ "/ " _ $SYSTEM.SQL.Functions.SQLCODE(SQLCODE)) 
		}

		Set %response.Status = 200
		do result.%Set("Update", ("TPID Deleted: " _ obj.id _", ID: " _ tpId.%Id() _", " _ tpId.%Oid()))
	}
	else
	{
		Set result = {"Error": ("TPID not found: " _ obj.id )}
	}
	Quit result


